SELECT sys_user.id, sys_user.nickname, sys_user.username, sys_user.status, sys_user.create_time, IF(sys_user_role.user_id IS NOT NULL, 1, 0) AS authorized FROM sys_user LEFT JOIN sys_user_role ON sys_user_role.user_id = sys_user.id AND sys_user_role.role_id = #{roleId} WHERE sys_user.del_flag = '0'
AND sys_user.nickname like concat('%', #{dto.nickname}, '%')
AND sys_user.username like concat('%', #{dto.username}, '%')
AND sys_user.status = #{dto.status}
AND sys_user_role.user_id IS NOT NULL
AND sys_user_role.user_id IS NULL
AND EXISTS (SELECT 1 FROM sys_user_dept WHERE sys_user_dept.user_id = sys_user.id AND sys_user_dept.dept_id IN
#{deptId}
)
ORDER BY authorized DESC, sys_user.create_time DESC

SELECT id, name, code, status, remark, menu_Id FROM sys_role
LEFT JOIN sys_role_menu ON sys_role.id = sys_role_menu.role_id
WHERE sys_role.id = #{roleId}
